import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 static int hooks;static final String P="dev/zomboid/turretpower/";
 static MethodInsnNode call(String owner,String n,String d){return new MethodInsnNode(INVOKESTATIC,owner,n,d,false);}
 static byte[] patch(byte[] b,String kind)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int before=hooks;
 if(kind.equals("turret")&&c.name.equals(P+"SoundEvents")){if(c.visibleAnnotations==null)throw new IllegalStateException("No original sound subscriber");c.visibleAnnotations.removeIf(a->a.desc.equals("Lnet/neoforged/fml/common/EventBusSubscriber;"));hooks++;}
 for(MethodNode m:c.methods){
  if(kind.equals("turret")&&c.name.equals("com/entropy/tacz_turrets/TACZTurrets")){
   if(m.name.equals("<init>")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new TypeInsnNode(NEW,P+"RegistryListener2"));x.add(new InsnNode(DUP));x.add(new MethodInsnNode(INVOKESPECIAL,P+"RegistryListener2","<init>","()V",false));x.add(new MethodInsnNode(INVOKEINTERFACE,"net/neoforged/bus/api/IEventBus","addListener","(Ljava/util/function/Consumer;)V",true));m.instructions.insertBefore(a,x);}hooks++;}
   if(m.name.equals("addCreative")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(call(P+"Scrap","creative","(Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);}hooks++;}
  }
  if(kind.equals("remains")&&c.name.equals("dev/zomboid/remains/CorpseBridge35")&&m.name.equals("body")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==RETURN){InsnList x=new InsnList();for(int i=0;i<3;i++)x.add(new VarInsnNode(ALOAD,i));x.add(call("dev/zomboid/remains/ScrapBridge2","body","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V"));m.instructions.insertBefore(a,x);}hooks++;}
  if(kind.equals("hordes")&&c.name.equals("dev/zomboid/hordes/LootProfiles")&&m.name.equals("container")){for(AbstractInsnNode a:m.instructions.toArray())if(a.getOpcode()==ARETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new VarInsnNode(ALOAD,2));x.add(call("dev/zomboid/hordes/ScrapBridge2","container","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;"));m.instructions.insertBefore(a,x);}hooks++;}
 }
 if(before==hooks)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);ClassNode v=new ClassNode();new ClassReader(w.toByteArray()).accept(v,0);for(MethodNode m:v.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(v.name,m);return w.toByteArray();}
 static byte[] listener(){String name=P+"RegistryListener2",evt="net/neoforged/neoforge/registries/RegisterEvent";ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC|ACC_FINAL,name,"Ljava/lang/Object;Ljava/util/function/Consumer<L"+evt+";>;","java/lang/Object",new String[]{"java/util/function/Consumer"});MethodVisitor m=w.visitMethod(ACC_PUBLIC,"<init>","()V",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESPECIAL,"java/lang/Object","<init>","()V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();m=w.visitMethod(ACC_PUBLIC,"accept","(L"+evt+";)V",null,null);m.visitCode();for(String helper:new String[]{"Sounds","Scrap"}){m.visitVarInsn(ALOAD,1);m.visitMethodInsn(INVOKESTATIC,P+helper,"register","(Ljava/lang/Object;)V",false);}m.visitInsn(RETURN);m.visitMaxs(1,2);m.visitEnd();m=w.visitMethod(ACC_PUBLIC|ACC_BRIDGE|ACC_SYNTHETIC,"accept","(Ljava/lang/Object;)V",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitVarInsn(ALOAD,1);m.visitTypeInsn(CHECKCAST,evt);m.visitMethodInsn(INVOKEVIRTUAL,name,"accept","(L"+evt+";)V",false);m.visitInsn(RETURN);m.visitMaxs(2,2);m.visitEnd();w.visitEnd();return w.toByteArray();}
 public static void main(String[]a)throws Exception{Map<String,byte[]> entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b,a[3]):b);}}try(var paths=Files.walk(Path.of(a[2]))){for(Path p:paths.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}int expected=a[3].equals("turret")?3:1;if(hooks!=expected)throw new IllegalStateException("hooks "+hooks+" != "+expected);if(a[3].equals("turret"))entries.put(P+"RegistryListener2.class",listener());try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println(a[3]+" hooks: "+hooks);}
}
